import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.Bqa2y7hU.js";const k=JSON.parse('{"title":"常见问题","description":"部署、机器人接入、平台权限、插件与订阅的高频问题：症状、原因与处理方式。","frontmatter":{"title":"常见问题","description":"部署、机器人接入、平台权限、插件与订阅的高频问题：症状、原因与处理方式。"},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1790419519000}'),p={name:"faq.md"};function o(e,s,l,r,h,g){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>按「症状 → 原因 → 处理方式」组织。遇到问题先用页面右上角的搜索，搜日志里的关键词。</p><h2 id="部署与启动" tabindex="-1">部署与启动 <a class="header-anchor" href="#部署与启动" aria-label="Permalink to &quot;部署与启动&quot;">​</a></h2><h3 id="启动后浏览器打不开控制台" tabindex="-1">启动后浏览器打不开控制台 <a class="header-anchor" href="#启动后浏览器打不开控制台" aria-label="Permalink to &quot;启动后浏览器打不开控制台&quot;">​</a></h3><p><strong>症状</strong></p><p>页面打不开、连接被拒绝；或服务日志里出现：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bind: Address already in use</span></span></code></pre></div><p><strong>原因</strong></p><ol><li><code>8080</code> 端口被别的程序占用；</li><li>服务器安全组 / 防火墙没有放通 <code>8080</code>；</li><li>服务其实没起来（例如数据库连不上，启动直接失败）。</li></ol><p><strong>处理方式</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 确认服务在跑</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 看端口有没有被占用</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tlnp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows（开发机）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ano</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> findstr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span></span></code></pre></div><p>端口被占用就改配置里的 <code>admin_listen</code>（例如换成 <code>8080</code> 之外的端口）后重启；是防火墙就放通端口；服务没起来就先看日志里的报错。</p><h3 id="安装向导进不去-想重新走一遍向导" tabindex="-1">安装向导进不去 / 想重新走一遍向导 <a class="header-anchor" href="#安装向导进不去-想重新走一遍向导" aria-label="Permalink to &quot;安装向导进不去 / 想重新走一遍向导&quot;">​</a></h3><p><strong>症状</strong></p><p>访问控制台直接进登录页，没有出现安装向导；或者想重装、重建管理员账号。</p><p><strong>原因</strong></p><p>安装向导只在<strong>首次启动</strong>（还没有初始化标记文件）时出现，安装完成后会写入标记文件，之后就一直走正常启动流程。</p><p><strong>处理方式</strong></p><div class="warning custom-block"><p class="custom-block-title">顺序不能反</p><p><strong>必须先停服务</strong>再删除标记文件，否则运行中的进程会把标记文件重新写回来。</p></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 1. 先停服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .installed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 2. 删除初始化标记（在程序目录里）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 3. 启动，会重新进入安装向导</span></span></code></pre></div><p>重新走向导会<strong>重写配置文件</strong>，数据库里的业务数据不受影响，但请先确认你已经知道数据库连接信息。</p><h3 id="程序必须从根目录启动" tabindex="-1">程序必须从根目录启动 <a class="header-anchor" href="#程序必须从根目录启动" aria-label="Permalink to &quot;程序必须从根目录启动&quot;">​</a></h3><p><strong>症状</strong></p><p>启动报错找不到配置文件 / 找不到插件目录 / 数据库迁移失败。</p><p><strong>原因</strong></p><p>配置、插件、迁移脚本都是按<strong>相对路径</strong>读取的，工作目录不对就会找不到。</p><p><strong>处理方式</strong></p><p>始终在程序所在目录启动，例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/xiaoyi_qq_c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./xbot</span></span></code></pre></div><p>用 systemd 管理时，服务单元里已经设好了工作目录，正常使用不用管。</p><h2 id="机器人连接" tabindex="-1">机器人连接 <a class="header-anchor" href="#机器人连接" aria-label="Permalink to &quot;机器人连接&quot;">​</a></h2><h3 id="机器人一直显示离线" tabindex="-1">机器人一直显示离线 <a class="header-anchor" href="#机器人一直显示离线" aria-label="Permalink to &quot;机器人一直显示离线&quot;">​</a></h3><p><strong>症状</strong></p><p>机器人详情页状态是离线；日志里反复出现重连。</p><p><strong>原因</strong></p><ol><li>AppID / AppSecret 填错或已重置；</li><li>服务器访问不了平台网关（网络受限、DNS 异常）；</li><li>平台主动断开连接做轮换 —— 这种情况框架会<strong>静默重连</strong>，日志里会写明是轮换，不是故障。</li></ol><p><strong>处理方式</strong></p><p>先看机器人详情页的<strong>日志</strong> Tab：如果看到「平台轮换连接，静默重连」，属于正常行为，等几秒会自动恢复；如果是鉴权失败，回到「添加机器人」核对凭据；如果一直连不上，检查服务器出网是否正常。</p><h3 id="群里发消息机器人不回复" tabindex="-1">群里发消息机器人不回复 <a class="header-anchor" href="#群里发消息机器人不回复" aria-label="Permalink to &quot;群里发消息机器人不回复&quot;">​</a></h3><p><strong>症状</strong></p><p>私聊正常，群里 @ 机器人也没反应；或者只有 @ 了才回。</p><p><strong>原因</strong></p><p>QQ 官方平台<strong>默认只推送 @ 机器人的消息</strong>。要收到群里全部消息，需要群主开启「群全量消息」授权。</p><p><strong>处理方式</strong></p><ol><li>确认机器人已在群里、且状态在线；</li><li>在控制台插件市场安装「全量申请」插件，生成授权深链发给群主，让群主在 QQ 里点开授权；</li><li>授权后群里未 @ 的消息也会推给机器人。</li></ol><h3 id="webhook-模式收不到平台事件" tabindex="-1">Webhook 模式收不到平台事件 <a class="header-anchor" href="#webhook-模式收不到平台事件" aria-label="Permalink to &quot;Webhook 模式收不到平台事件&quot;">​</a></h3><p><strong>症状</strong></p><p>用 Webhook 方式接入，平台上配置好了回调地址，但机器人收不到任何消息。</p><p><strong>原因</strong></p><p>回调地址里的域名是<strong>动态推导</strong>的：没配公网域名时会退化成当前请求的 Host（可能是内网地址或 <code>localhost</code>），平台自然回调不到。</p><p><strong>处理方式</strong></p><p>在「平台设置 → 站点」里显式配置回调协议与公网域名，再用控制台给出的回调地址回填到平台。反向代理要转发 <code>Host</code> 头。详见 <a href="/RuaBot.Doc/platforms/callback">回调地址与公网域名</a>。</p><h2 id="平台权限" tabindex="-1">平台权限 <a class="header-anchor" href="#平台权限" aria-label="Permalink to &quot;平台权限&quot;">​</a></h2><h3 id="接口返回「应用无接口访问权限」" tabindex="-1">接口返回「应用无接口访问权限」 <a class="header-anchor" href="#接口返回「应用无接口访问权限」" aria-label="Permalink to &quot;接口返回「应用无接口访问权限」&quot;">​</a></h3><p><strong>症状</strong></p><p>调用群信息、群成员、禁言、入群审批等能力时失败，返回内容里带：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;应用无接口访问权限&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11253</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>原因</strong></p><p>该接口属于平台<strong>需要单独开通/加白名单</strong>的能力，当前机器人还没有权限。</p><p><strong>处理方式</strong></p><p>到 QQ 开放平台为该机器人开通对应能力。<strong>插件的日志里会原样保留这条错误</strong>，所以先看机器人的日志页确认是哪一步被拒，再对照平台的权限列表去开通。</p><h3 id="按钮点了没反应-提示无权限" tabindex="-1">按钮点了没反应 / 提示无权限 <a class="header-anchor" href="#按钮点了没反应-提示无权限" aria-label="Permalink to &quot;按钮点了没反应 / 提示无权限&quot;">​</a></h3><p><strong>症状</strong></p><p>群里播报带按钮，点击后没有任何反应，或者客户端提示无权限。</p><p><strong>原因</strong></p><p>绝大多数情况是<strong>按钮本身没有被平台接受</strong>：按钮的权限、类型配置不正确时，客户端会直接拒绝点击，框架收不到任何回调（所以日志里什么都看不到）。</p><p><strong>处理方式</strong></p><ol><li>确认这是 QQ 官方平台的机器人（<strong>按钮只在 QQ 官方可用</strong>，其它平台发送时不会渲染成按钮，需要用文字指令完成同样的事）；</li><li>确认群管类插件的「使用按钮」开关是开的；</li><li>点不动时，直接用文字指令完成同样的事（例如回复「同意 1」），不影响功能；</li><li>如果是插件开发者、自己在生成按钮，检查按钮 JSON 的字段是否符合平台规范（按钮类型、权限类型、必填的兜底文案）。</li></ol><h3 id="禁言-踢人失败" tabindex="-1">禁言 / 踢人失败 <a class="header-anchor" href="#禁言-踢人失败" aria-label="Permalink to &quot;禁言 / 踢人失败&quot;">​</a></h3><p><strong>症状</strong></p><p>群里发指令后提示操作失败。</p><p><strong>原因</strong></p><ol><li>机器人<strong>不是群管理员</strong>；</li><li>该群管理接口未在平台开通。</li></ol><p><strong>处理方式</strong></p><p>让群主把机器人设为群管理员；再去 QQ 开放平台确认相关能力已开通。操作结果会记进插件的审计记录，带失败原因。</p><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><h3 id="上传插件报「无法读取插件元数据」" tabindex="-1">上传插件报「无法读取插件元数据」 <a class="header-anchor" href="#上传插件报「无法读取插件元数据」" aria-label="Permalink to &quot;上传插件报「无法读取插件元数据」&quot;">​</a></h3><p><strong>症状</strong></p><p>管理后台上传插件包时被拒绝。</p><p><strong>原因</strong></p><p>插件没有导出元数据符号（通常是没有用官方注册宏），或者二进制文件已损坏。</p><p><strong>处理方式</strong></p><p>用官方 SDK 的注册宏（<code>BOT_REGISTER_PLUGIN</code> 系列）重新编译。自己写构建脚本时，注意<strong>不要漏掉注册宏所在的源文件</strong>。</p><h3 id="插件加载失败-提示-abi-不兼容" tabindex="-1">插件加载失败 / 提示 ABI 不兼容 <a class="header-anchor" href="#插件加载失败-提示-abi-不兼容" aria-label="Permalink to &quot;插件加载失败 / 提示 ABI 不兼容&quot;">​</a></h3><p><strong>症状</strong></p><p>日志里出现插件被拒绝加载，提示版本不匹配。</p><p><strong>原因</strong></p><p>插件与框架的二进制接口版本不匹配（用更新的 SDK 编的插件放到更旧的框架上）。</p><p><strong>处理方式</strong></p><p>升级框架，或改用与当前框架版本匹配的 SDK 重新编译插件。规则见 <a href="/RuaBot.Doc/plugin-dev/abi">ABI 与兼容规则</a>。</p><h3 id="插件装上去了但完全不触发" tabindex="-1">插件装上去了但完全不触发 <a class="header-anchor" href="#插件装上去了但完全不触发" aria-label="Permalink to &quot;插件装上去了但完全不触发&quot;">​</a></h3><p><strong>症状</strong></p><p>插件显示已启用，群里发消息没有任何反应。</p><p><strong>原因</strong></p><p>按可能性排序：</p><ol><li>插件没有声明订阅该事件（事件掩码没打开）；</li><li>插件没装到<strong>这台</strong>机器人上（装到别的机器人去了）；</li><li>群消息收不到 —— 需要全量消息授权（见上文）；</li><li>插件的触发条件没命中（例如只处理 @ 消息，而这条消息没 @ 机器人）。</li></ol><p><strong>处理方式</strong></p><p>到机器人详情页确认「插件」Tab 里该插件已启用；查看插件自己的日志输出；用「回声」这类最小插件验证机器人本身能不能收发消息，快速区分是插件问题还是接入问题。</p><p>如果<strong>只有某一台</strong>机器人这样、其他机器人上的同一个插件都正常，并且这台机器人是<strong>刚刚新建的</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span></code></pre></div><p>老版本存在&quot;新建机器人之后，插件事件分发不到它&quot;的问题，判断依据就是这个组合。升级到最新版本并重启即可，之前已经产生的数据不会丢，重启后插件会自己补上。</p><h3 id="提示插件位不足" tabindex="-1">提示插件位不足 <a class="header-anchor" href="#提示插件位不足" aria-label="Permalink to &quot;提示插件位不足&quot;">​</a></h3><p><strong>症状</strong></p><p>安装插件被拒绝，提示超出配额。</p><p><strong>原因</strong></p><p>套餐里的<strong>插件位</strong>用完了。</p><p><strong>处理方式</strong></p><p>卸载不用的插件，或升级套餐。当前配额可以在订阅中心看到。</p><h3 id="插件面板能打开但操作都失败" tabindex="-1">插件面板能打开但操作都失败 <a class="header-anchor" href="#插件面板能打开但操作都失败" aria-label="Permalink to &quot;插件面板能打开但操作都失败&quot;">​</a></h3><p><strong>症状</strong></p><p>插件面板页面能显示，但保存配置、执行动作都提示失败。</p><p><strong>原因</strong></p><ol><li>插件<strong>没有安装（绑定）到这台机器人</strong>；</li><li>插件被停用；</li><li>面板会话过期（面板地址里带一次性令牌，长时间停留会失效）。</li></ol><p><strong>处理方式</strong></p><p>到机器人详情页的「插件」Tab 确认已安装且启用；关掉面板重新打开即可换新令牌。</p><h2 id="账号与订阅" tabindex="-1">账号与订阅 <a class="header-anchor" href="#账号与订阅" aria-label="Permalink to &quot;账号与订阅&quot;">​</a></h2><h3 id="注册时提示-qq-号无效" tabindex="-1">注册时提示 QQ 号无效 <a class="header-anchor" href="#注册时提示-qq-号无效" aria-label="Permalink to &quot;注册时提示 QQ 号无效&quot;">​</a></h3><p><strong>原因</strong></p><p>注册<strong>必须填 QQ 号</strong>，且格式被限定为 5–15 位、不以 0 开头的纯数字。</p><p><strong>处理方式</strong></p><p>填正确的 QQ 号即可。如果服务商要求邮箱验证，按提示去邮箱点验证链接。</p><h3 id="忘记密码收不到邮件" tabindex="-1">忘记密码收不到邮件 <a class="header-anchor" href="#忘记密码收不到邮件" aria-label="Permalink to &quot;忘记密码收不到邮件&quot;">​</a></h3><p><strong>原因</strong></p><p>服务商没有配置邮件发送（SMTP），或关闭了自助找回密码。</p><p><strong>处理方式</strong></p><p>联系服务商重置，或在有管理员权限的情况下到「平台设置 → 邮件」里把 SMTP 配好。生产环境下即便配置正确，也不会把重置链接直接显示在页面上，而是发到邮箱。</p><h3 id="机器人回复变慢" tabindex="-1">机器人回复变慢 <a class="header-anchor" href="#机器人回复变慢" aria-label="Permalink to &quot;机器人回复变慢&quot;">​</a></h3><p><strong>处理方式</strong></p><p>先看控制台的「服务器监控」页：CPU、内存、进程占用、运行时长、消息吞吐都在这里。多数情况是单机负载偏高或某个插件在等外部接口，可以结合机器人日志定位。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/deploy/install">安装</a>：部署流程</li><li><a href="/RuaBot.Doc/deploy/ops">备份与运维</a>：日常运维与故障排查</li><li><a href="/RuaBot.Doc/platforms/overview">机器人接入</a>：接入方式的差异</li></ul>`,131)])])}const c=a(p,[["render",o]]);export{k as __pageData,c as default};
